def countFairRemovals(nums):
    E = sum(nums[0::2])
    O = sum(nums[1::2])
    pe = po = 0
    count = 0
    for i, x in enumerate(nums):
        se = E - pe - (x if i % 2 == 0 else 0)
        so = O - po - (x if i % 2 == 1 else 0)
        if pe + so == po + se:
            count += 1
        if i % 2 == 0:
            pe += x
        else:
            po += x
    return count
